/* Original syllabus, arranged around a visible learning journey. Reviewed 7 November 2026. */
const learningPhases=[
 {id:'start',title:'Start with purpose & a safe workspace',short:'Orient',tone:'mint',label:'START HERE',modules:['mindset','architecture','labsetup'],before:'No cybersecurity experience required. Bring curiosity and basic computer familiarity.',goal:'Explain what needs protecting, define written scope, and plan an isolated practice environment.',outcome:'An asset-and-risk sketch, a lab diagram, and a preflight checklist.',checkpoint:'Can you distinguish a threat from a vulnerability and explain which networks your lab can reach?',practice:'#field/terminal',practiceLabel:'Try the simulated terminal',videos:['full','messer'],pdf:'lab',},
 {id:'systems',title:'Understand the systems you protect',short:'Understand',tone:'sky',label:'BUILD YOUR BASE',modules:['networks','linux','windows','identity'],before:'Complete stage 01. Be able to describe your lab boundary and learning scope.',goal:'Follow a network request, reason about operating-system permissions, and separate authentication from authorization.',outcome:'A packet-journey diagram and a least-privilege identity checklist.',checkpoint:'Can you explain DNS, TLS, file permissions, hashing, and account recovery in your own words?',practice:'#field',practiceLabel:'Work through the beginner challenges',videos:['networking','accounts','savill']},
 {id:'assess',title:'Discover, assess & validate',short:'Assess',tone:'gold',label:'OBSERVE BEFORE YOU ACT',modules:['recon','assessment','mitm'],before:'Complete stages 01–02: networks, operating systems, identity, and a defined training boundary.',goal:'Turn scoped discovery into an inventory, validate scan findings, and reason about trust in intercepted traffic.',outcome:'A scoped inventory with evidence, confidence, and prioritized validation steps.',checkpoint:'Can you explain why an open port or scanner match is a clue rather than proof of a vulnerability?',practice:'#field/scan',practiceLabel:'Interpret a synthetic scan',videos:['tcm-ethical','networking']},
 {id:'applications',title:'Secure applications & accounts',short:'Secure',tone:'violet',label:'CONNECT WEAKNESSES TO FIXES',modules:['web','webdepth','credentialaudit','systems'],before:'Complete stage 03. Understand HTTP requests, permissions, and authorized assessment.',goal:'Connect web weaknesses, credential abuse, and post-access behavior to root causes and preventive controls.',outcome:'A developer-friendly training-lab report with a fix and retest plan.',checkpoint:'Can you describe the failed trust boundary, show minimal evidence, and propose a root-cause fix?',practice:'#project/appsec',practiceLabel:'Build the web security project',videos:['burp','tcm-ethical'],pdf:'web'},
 {id:'defend',title:'Detect, investigate & recover',short:'Defend',tone:'peach',label:'TURN SIGNALS INTO DECISIONS',modules:['defense','cloud','forensics'],before:'Complete stage 04, or revisit the systems stage if logs and identity flows are unfamiliar.',goal:'Correlate events, secure cloud identity boundaries, preserve evidence, and plan trusted recovery.',outcome:'A synthetic incident timeline and a cloud access review.',checkpoint:'Can you separate facts from hypotheses and explain your escalation and recovery decision?',practice:'#labs/triage',practiceLabel:'Investigate a suspicious sign-in',videos:['tcm-soc','savill'],pdf:'soc'},
 {id:'specialize',title:'Explore specialist security work',short:'Specialize',tone:'rose',label:'CHOOSE YOUR DEPTH',modules:['wireless','malware','intel','mobileot','ai'],before:'Complete the shared foundation and stage 05. Use specialist topics to choose where to study more deeply.',goal:'Recognize the distinct trust boundaries of wireless, executable, intelligence, mobile, OT, and AI systems.',outcome:'One specialist study brief: a threat model, useful evidence, limitations, and a deeper learning plan.',checkpoint:'Can you explain one specialist risk and the evidence needed to evaluate it without overclaiming?',practice:'#careers',practiceLabel:'Compare career directions',videos:['full','tcm-soc']},
 {id:'launch',title:'Govern responsibly. Build your portfolio.',short:'Launch',tone:'mint',label:'FINISH WITH EVIDENCE',modules:['grc','professional','career'],before:'Finish the shared stages and explore a specialist direction. Bring one practical project to refine.',goal:'Translate security work into risk decisions, a scoped professional report, and a focused career plan.',outcome:'One complete, sanitized portfolio case study and a personal four-week next-step plan.',checkpoint:'Can you demonstrate the problem, evidence, decision, remediation, retest, and limitations of your project?',practice:'#labs',practiceLabel:'Choose your portfolio project',videos:['messer','savill'],pdf:'roadmap'}
];
const guidedModuleIds=learningPhases.flatMap(p=>p.modules);
const guidedModules=()=>guidedModuleIds.map(id=>modules.find(m=>m.id===id));
const phaseForModule=id=>learningPhases.find(p=>p.modules.includes(id));
const moduleWatch=id=>videos.filter(v=>v.modules?.includes(id)).slice(0,2);
const phaseLessons=p=>p.modules.reduce((n,id)=>n+modules.find(m=>m.id===id).lessons.length,0);
const phaseCompleted=p=>p.modules.reduce((n,id)=>n+modules.find(m=>m.id===id).lessons.filter((l,i)=>state.done.includes(`${id}:${i}`)).length,0);
const activePhases=()=>learningPhases;
let curriculumQuery='',videoQuery='',videoTopic='All';

function flowStrip(){return `<ol class="journey-strip" aria-label="Suggested learning sequence">${activePhases().map((p,i)=>`<li data-tone="${p.tone}"><a href="#curriculum/${p.id}"><span>${String(i+1).padStart(2,'0')}</span><b>${p.short}</b><small>${p.modules.length} modules</small></a></li>`).join('')}</ol>`;}
function startingPoint(){const [,id,index]=nextLesson().slice(1).split('/');const m=modules.find(m=>m.id===id);if(!m)return `<div class="next-step"><div><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>The course is complete. Keep building.</h2><p>Review your evidence, strengthen a project, and plan your next specialization.</p></div><a class="btn" href="#progress">Review my progress ↗</a></div>`;const p=phaseForModule(m.id);return `<div class="next-step"><span class="next-icon">${icon(m.icon)}</span><div><div class="eyebrow">${totalDone()?'YOUR NEXT STEP':'YOUR STARTING POINT'} · STAGE ${String(learningPhases.indexOf(p)+1).padStart(2,'0')}</div><h2>${m.lessons[Number(index)].title}</h2><p>${m.title} · Read, watch, practice, then check your understanding.</p></div><a class="btn" href="${nextLesson()}">${totalDone()?'Continue lesson':'Let’s begin'} →</a></div>`;}
function learningRhythm(){return `<div class="learning-rhythm" aria-label="How to learn each topic">${[['01','Read','Understand the concept.'],['02','Watch','See a practitioner explain.'],['03','Practice','Create a small piece of evidence.'],['04','Check','Explain it. Test your reasoning.']].map(([n,t,d])=>`<div><span>${n}</span><b>${t}</b><small>${d}</small></div>`).join('')}</div>`;}
function curriculumModule(m){const count=m.lessons.filter((l,i)=>state.done.includes(`${m.id}:${i}`)).length;const watches=moduleWatch(m.id);return `<section class="syllabus-module" aria-labelledby="module-${m.id}"><div class="syllabus-module-heading"><div><div class="eyebrow">MODULE ${String(guidedModuleIds.indexOf(m.id)+1).padStart(2,'0')} · ${m.time} READING & EXERCISES</div><h3 id="module-${m.id}">${m.title}</h3></div><span class="completion-label">${count}/${m.lessons.length} complete</span></div><p>${m.subtitle}</p><div class="tags">${m.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><ol class="syllabus-lessons">${m.lessons.map((l,i)=>`<li><a href="#lesson/${m.id}/${i}"><span class="lesson-status ${state.done.includes(`${m.id}:${i}`)?'is-done':''}">${state.done.includes(`${m.id}:${i}`)?'✓':String(i+1).padStart(2,'0')}</span><span>${l.title}</span><span aria-hidden="true">↗</span></a></li>`).join('')}</ol><div class="module-study-links"><a href="#checks/${m.id}">Review ${m.lessons.length} knowledge checks →</a>${watches.map(v=>`<button data-video="${v.id}">▷ ${v.provider}: ${v.shortTitle||v.title}</button>`).join('')}</div></section>`;}
function phaseCard(p,query='',selected=''){const idx=learningPhases.indexOf(p),done=phaseCompleted(p),total=phaseLessons(p);const all=p.modules.map(id=>modules.find(m=>m.id===id));const queryMatch=m=>`${m.title} ${m.subtitle} ${m.skills.join(' ')} ${m.lessons.map(l=>l.title).join(' ')}`.toLowerCase().includes(query.toLowerCase());const matches=query?all.filter(queryMatch):all; if(query&&!matches.length&&!`${p.title} ${p.goal} ${p.outcome}`.toLowerCase().includes(query.toLowerCase()))return '';const show=matches.length?matches:all;return `<li class="flow-step" data-tone="${p.tone}"><details class="curriculum-phase" id="phase-${p.id}" ${query||selected===p.id?'open':''}><summary><span class="phase-number">${done===total?'✓':String(idx+1).padStart(2,'0')}</span><span class="phase-summary"><small>${p.label} ${p.course==='data'?'<span style="display:inline-block;padding:2px 8px;border-radius:99px;background:rgba(235,160,82,0.18);color:var(--gold);font-weight:700;font-size:10px;margin-left:6px">DATA &amp; MLOPS</span>':'<span style="display:inline-block;padding:2px 8px;border-radius:99px;background:rgba(85,214,190,0.18);color:var(--mint);font-weight:700;font-size:10px;margin-left:6px">CYBER</span>'}</small><h2>${p.title}</h2><span>${p.modules.length} modules · ${total} lessons · ${done}/${total} complete</span></span><span class="phase-toggle" aria-hidden="true">+</span></summary><div class="phase-content"><p class="phase-goal">${p.goal}</p><div class="phase-context"><div><b>Before you begin</b><p>${p.before}</p></div><div><b>What you’ll produce</b><p>${p.outcome}</p></div></div>${show.map(curriculumModule).join('')}<div class="phase-milestone"><div class="eyebrow">STAGE ${String(idx+1).padStart(2,'0')} · READINESS CHECK</div><p>${p.checkpoint}</p><a class="btn small" href="${p.practice}">${p.practiceLabel} →</a>${idx<learningPhases.length-1?`<a class="text-link" href="#curriculum/${learningPhases[idx+1].id}">Next: ${learningPhases[idx+1].short} →</a>`:'<a class="text-link" href="#progress">Review your learning evidence →</a>'}</div></div></details></li>`;}
function curriculumPage(selected=''){const active=activePhases();return shell(`${heading('YOUR FLEXIBLE COURSE MAP','From first principles to production & defense.','A clear beginning, connected syllabi, and practical portfolio projects. Follow the stages in order, or revisit a topic when your project needs it.')}<div class="course-actions"><a class="btn outline small" href="#syllabus">Read the complete syllabus ↗</a><span>${active.length} stages · ${active.flatMap(p=>p.modules).length} modules · ${active.reduce((n,p)=>n+phaseLessons(p),0)} lessons</span></div>${flowStrip()}${startingPoint()}<div class="section-top"><div><h2>One curriculum. A connected journey.</h2><p>Open a stage to see what to learn, what to build, and when to move on.</p></div></div>${learningRhythm()}<div class="curriculum-tools"><label class="screen-reader" for="curriculum-search">Search the syllabus</label><input id="curriculum-search" class="search" type="search" placeholder="Search a topic — networks, lakehouse, MLOps, forensics…" value="${esc(curriculumQuery)}"><button class="btn small outline" data-flow-expand="true">Expand all</button><button class="btn small outline" data-flow-expand="false">Collapse all</button></div><p id="curriculum-count" class="result-count" role="status"></p><ol class="curriculum-flow" id="curriculum-flow">${active.map(p=>phaseCard(p,curriculumQuery,selected)).join('')}</ol><div class="journey-finish"><span>${icon('compass')}</span><div><div class="eyebrow">YOUR DESTINATION</div><h2>A portfolio you can explain.</h2><p>Finish with well-documented projects, chosen career directions, and concrete plans for deeper practice. Every stage remains open to you.</p></div><a class="btn outline small" href="#careers">Find your next direction →</a></div><div class="banner"><b>Study at your own pace.</b> Module times estimate the short on-site lessons and exercises; videos, external labs, and portfolio projects add study time. All stages stay open to you. Progress is self-reported and saved in this browser.</div>`,'curriculum');}
function updateCurriculum(){const selected=location.hash.split('/')[1]||'';const rendered=activePhases().map(p=>phaseCard(p,curriculumQuery,selected)).filter(Boolean);$('#curriculum-flow').innerHTML=rendered.join('')||'<li class="empty">No syllabus topics match. Try a broader term or clear the search.</li>';$('#curriculum-count').textContent=curriculumQuery?`${rendered.length} matching stages · Search includes module titles, skills, and all lesson titles.`:`${activePhases().length} connected stages · Select any stage to open its syllabus.`;}
function syllabusPage(){return shell(`<a class="back" href="#curriculum">← Back to the curriculum map</a>${heading('NXGENVARSITY · COURSE SYLLABUS','Cybersecurity, from foundations to practice.','A self-paced syllabus for engineering students. Learn systems, assess responsibly, build defenses, explore a specialization, and communicate your evidence.')}<div class="course-actions"><button class="btn small" id="download-syllabus">Download syllabus (.md) ↓</button><a class="text-link" href="${nextLesson()}">Start or continue learning →</a></div><div class="syllabus-overview"><div><h2>Who this is for</h2><p>Engineering students and independent learners. Begin with basic computer use; Linux, networking, and programming concepts are introduced in the course.</p></div><div><h2>What you will demonstrate</h2><p>System and identity reasoning, scoped assessment, defensive investigation, risk communication, and one reproducible portfolio case study.</p></div><div><h2>How to use the syllabus</h2><p>Work through stages 01–05 in sequence, use stage 06 to explore depth, then complete stage 07 with a chosen project. Each lesson has a practice prompt, notes, and a knowledge check.</p></div><div><h2>Assessment & completion</h2><p>75 short lessons, 75 formative checks, 10 starter challenges, and four project choices. Complete the lessons, revisit missed checks, and finish one project with evidence and limitations. This is an independent study companion, not an accredited qualification.</p></div></div>${learningRhythm()}${learningPhases.map((p,i)=>`<section class="syllabus-section" data-tone="${p.tone}"><div class="eyebrow">STAGE ${String(i+1).padStart(2,'0')} · ${p.modules.length} MODULES · ${phaseLessons(p)} LESSONS</div><h2>${p.title}</h2><p>${p.goal}</p><p><b>Prerequisite:</b> ${p.before}</p><ol class="syllabus-outline">${p.modules.map(id=>{const m=modules.find(m=>m.id===id);return `<li><a href="#lesson/${m.id}/0"><b>${m.title} ↗</b></a><span>${m.skills.join(' · ')}</span><ul>${m.lessons.map((l,j)=>`<li><a href="#lesson/${m.id}/${j}">${l.title} →</a></li>`).join('')}</ul></li>`}).join('')}</ol><div class="syllabus-outcome"><b>Evidence to produce</b><p>${p.outcome}</p><a class="text-link" href="${p.practice}">${p.practiceLabel} →</a></div><div class="module-study-links">${p.videos.map(id=>{const v=videos.find(v=>v.id===id);return `<button data-video="${id}">▷ ${v.provider} · ${v.shortTitle||v.title}</button>`}).join('')}</div></section>`).join('')}<div class="section-top"><div><h2>Your study companions</h2><p>Use the existing branded PDFs alongside the online lessons.</p></div></div>${pdfDownloads()}<p class="source-credit">Syllabus reviewed 7 November 2026. External training belongs to its creators. Learning stages organize all 25 existing modules; they do not imply full professional proficiency from short lessons alone.</p>`,'curriculum');}
function syllabusMarkdown(){return '# NxGenVarsity · Cybersecurity syllabus\n\n7 stages · 25 modules · 75 lessons · 75 formative checks\n\nAudience: Engineering students and independent learners. Basic computer familiarity is sufficient to begin.\n\nMethod: Read → Watch → Practice → Check. Complete stages 1–5, explore a specialization in stage 6, then finish stage 7 with one portfolio project. Module estimates exclude external video, lab, and project time.\n\n'+learningPhases.map((p,i)=>`## ${i+1}. ${p.title}\n\nGoal: ${p.goal}\n\nPrerequisite: ${p.before}\n\n${p.modules.map(id=>{const m=modules.find(m=>m.id===id);return `### ${m.title}\n\nSkills: ${m.skills.join(', ')}\n\n${m.lessons.map((l,j)=>`- [${l.title}](https://cyber-studio-engineering.maheshp.chatgpt.site/#lesson/${m.id}/${j})`).join('\n')}\n`}).join('\n')}\nEvidence: ${p.outcome}\n\nReadiness check: ${p.checkpoint}\n\nWatch:\n${p.videos.map(id=>{const v=videos.find(v=>v.id===id);return `- ${v.provider}: ${v.title} — https://www.youtube.com/watch?v=${v.video}`}).join('\n')}\n`).join('\n')+'\n## Completion\n\nComplete the lessons and formative checks; produce one project with scope, evidence, reasoning, remediation, retest, and limitations. Progress is self-reported. This is an independent learning companion, not an accredited qualification.\n\nReviewed 7 November 2026.\n';}
function reviewQueue(){const list=[];for(const m of guidedModules())m.lessons.forEach((l,i)=>{if(state.answers[`${m.id}:${i}`]===false)list.push({m,l,i});});return list;}
function reviewPage(index){const queue=reviewQueue();const total=queue.length;
 if(!total)return shell(`<a class="back" href="#checks">← Back to knowledge checks</a>${heading('REVIEW YOUR MISTAKES','Nothing to revisit. Yet.','This page collects the questions you answered incorrectly, so a wrong answer becomes a prompt to think again rather than a dead end.')}<div class="review-empty"><span class="play-circle">✓</span><div><h2>Your review list is clear.</h2><p>Answer a knowledge check incorrectly and it will appear here. Correct answers drop off automatically.</p></div></div><div class="toolbar"><a class="btn" href="${nextLesson()}">Continue learning ↗</a><a class="btn outline" href="#checks">Browse all checks</a></div>`,'checks');
 const n=Math.max(0,Math.min(Number(index)||0,total-1));const item=queue[n];const key=`${item.m.id}:${item.i}`;
 // Options keep their real identity but are displayed in a stable per-question shuffle so position cannot be memorized.
 const order=item.l.options.map((_,j)=>j).sort((a,b)=>((a+item.i*7+item.m.id.length)%3)-((b+item.i*7+item.m.id.length)%3)||a-b);
 return shell(`<a class="back" href="#checks">← Back to knowledge checks</a>${heading('REVIEW YOUR MISTAKES','One question at a time.','These are the checks you answered incorrectly. Work through them in any order; a correct answer removes the question from this list.')}<div class="review-progress" role="status"><b>${n+1} of ${total}</b> to revisit · ${total-n-1} after this one</div><article class="article review-card" data-review="${key}"><div class="eyebrow">${phaseForModule(item.m.id).title} · ${item.m.title}</div><h2>${item.l.q}</h2><div class="answers">${order.map(j=>`<button class="answer" data-answer="${j}" data-module="${item.m.id}" data-lesson="${item.i}"><span>${'ABC'[j]}.</span>${item.l.options[j]}</button>`).join('')}</div><div class="feedback" role="status"></div><div class="review-links"><a class="text-link" href="#lesson/${item.m.id}/${item.i}">Reread this lesson →</a><button class="btn small outline" data-review-next="${n+1<total?'#checks/review/'+(n+1):'#checks/review/0'}" hidden>Next question →</button></div></article>`,'checks');}
function checksPage(id,sub){if(id==='review')return reviewPage(sub);if(String(id||'').startsWith('review/'))return reviewPage(String(id).split('/')[1]);const m=modules.find(m=>m.id===id)||guidedModules().find(m=>!m.lessons.every((l,i)=>state.answers[`${m.id}:${i}`]))||guidedModules()[0];const missed=reviewQueue().length;const lessonChecks=m.lessons.map((l,i)=>`<section class="question" aria-labelledby="check-${i}"><div class="eyebrow muted">LESSON ${i+1}</div><h3 id="check-${i}">${l.q}</h3><div class="answers">${l.options.map((o,j)=>`<button class="answer ${state.answers[`${m.id}:${i}`]&&j===l.correct?'correct':''}" data-answer="${j}" data-module="${m.id}" data-lesson="${i}"><span>${'ABC'[j]}.</span>${o}</button>`).join('')}</div><div class="feedback" role="status">${state.answers[`${m.id}:${i}`]?'✓ '+l.explanation:''}</div><a class="text-link" href="#lesson/${m.id}/${i}">Review this lesson →</a></section>`).join('');const bankChecks=m.quizBank?.length?`<div class="section-top"><div><h2>Complete module quiz</h2><p>${m.quizBank.length} questions from the Data & MLOps workbook</p></div></div>${m.quizBank.map((q,i)=>`<section class="question" aria-labelledby="bank-check-${i}"><div class="eyebrow muted">QUIZ QUESTION ${i+1}</div><h3 id="bank-check-${i}">${q.question}</h3><div class="answers">${q.options.map((o,j)=>`<button class="answer ${state.answers[`quiz:${m.id}:${i}`]===true&&j===q.correct?'correct':''}" data-bank-answer="${j}" data-bank-module="${m.id}" data-bank-index="${i}"><span>${'ABC'[j]}.</span>${o}</button>`).join('')}</div><div class="feedback" role="status">${state.answers[`quiz:${m.id}:${i}`]===true?'✓ '+q.explanation:''}</div></section>`).join('')}`:'';return shell(`${heading('CHECK YOUR UNDERSTANDING','Explain it. Then test your reasoning.','Revisit formative questions and the complete Data & MLOps module quiz bank.')}<div class="review-banner"><div><b>${missed?`${missed} check${missed===1?'':'s'} to revisit`:'All answered checks are correct'}</b><p>${missed?'Questions you answered incorrectly are collected here. Clear them one at a time.':'Answer a check incorrectly and it will appear here for another attempt.'}</p></div><a class="btn small ${missed?'':'outline'}" href="#checks/review">${missed?'Start review →':'How review works →'}</a></div><div class="toolbar"><label for="check-module">Choose a module</label><select id="check-module">${guidedModules().map(mo=>`<option value="${mo.id}" ${mo.id===m.id?'selected':''}>${String(guidedModuleIds.indexOf(mo.id)+1).padStart(2,'0')} · ${mo.title}</option>`).join('')}</select></div><article class="article"><div class="eyebrow">${phaseForModule(m.id).title}</div><h2>${m.title}</h2>${lessonChecks}${bankChecks}<a class="btn outline small" href="#curriculum/${phaseForModule(m.id).id}">Return to this learning stage →</a></article>`,'checks');}
